import{uiSet,uiParts,uiAttribute,uiMessage,watchPracticeUi}from './practice-i18n.js';
import{qiblaPart,QIBLA_UI_SOURCE,qiblaMapControls}from './qibla-ui.js';
import{bearing}from './prayers.js';
import{mapPoint,qiblaMapRay}from './qibla-map-core.js';
import{getQiblaPosition}from './qibla-access.js';
let library;
async function leaflet(){
 if(!document.getElementById('qibla-map-style')){const css=document.createElement('link');css.id='qibla-map-style';css.rel='stylesheet';css.href=new URL('./vendor/leaflet/leaflet.css',import.meta.url).href;document.head.append(css);}
 if(!library)library=import('./vendor/leaflet/leaflet.js').catch(error=>{library=null;throw error;});await library;return window.L;
}
export function qiblaMapMarkup(){return '<div class="qibla-map-heading"><strong data-i18n="qiblaUi.mapHeading">Кибла на карте</strong><span data-i18n="qiblaUi.north">Север ↑</span></div><p class="qibla-map-help" data-i18n="qiblaUi.fallbackMapHelp">Приблизьте дом и коснитесь нужной точки — золотая линия укажет Киблу.</p><div id="qibla-map-canvas" class="qibla-map-canvas" role="region" aria-label="Карта местности и направление Киблы" data-i18n-aria-label="qiblaUi.mapRegion"></div><div class="qibla-map-actions"><button type="button" class="button secondary" id="qibla-map-locate" aria-label="Определить моё местоположение" data-i18n-aria-label="qiblaUi.locateLabel" data-i18n="qiblaUi.myLocation">Моё место</button><button type="button" class="button secondary" id="qibla-map-city" aria-label="К выбранному городу" data-i18n-aria-label="qiblaUi.chosenCityLabel" data-i18n="qiblaUi.toCity">К городу</button></div><p id="qibla-map-status" role="status" aria-live="polite" data-i18n="qiblaUi.openingMap">Открываем карту…</p><p class="qibla-map-privacy" data-i18n="qiblaUi.fallbackMapPrivacy">Карта — OpenStreetMap. Сервис получает сетевой адрес и область просмотра. Текущее место определяется при открытии Киблы с вашего разрешения. Точка остаётся в этом разделе и не меняет город намазов.</p>';}
export function mountQiblaMap(host,{city,position=null,loadLibrary=leaflet,getPosition=getQiblaPosition}={}){
 const cityPoint=city&&mapPoint(city.latitude,city.longitude),initial=position&&mapPoint(position.coords?.latitude,position.coords?.longitude);
 host.innerHTML=qiblaMapMarkup();const stopLanguage=watchPracticeUi(host,()=>qiblaMapControls(host));let closed=false,map=null,leafletApi=null,point=initial||cityPoint,label=initial?'Местоположение устройства':cityPoint?'Центр выбранного города: '+city.name:'Выбранная точка',marker=null,ray=null,arrow=null,accuracy=null,metres=initial&&Number.isFinite(position.coords.accuracy)?Math.max(0,position.coords.accuracy):0,locating=null,request=0,hadTileError=false,following=true,currentPosition=initial?position:null;
 const canvas=host.querySelector('#qibla-map-canvas'),status=host.querySelector('#qibla-map-status'),locate=host.querySelector('#qibla-map-locate'),back=host.querySelector('#qibla-map-city');back.disabled=!cityPoint;
 function update(){if(closed||!map)return;if(!point){for(const old of [marker,ray,arrow,accuracy])if(old)map.removeLayer(old);marker=null;ray=null;arrow=null;accuracy=null;uiSet(status,"qiblaUi.mapLocationUnknown","Текущее место не определено. Нажмите «Моё место» или выберите точку на карте.");return;}const heading=bearing(point.latitude,point.longitude),angle=Number.isFinite(heading)?Math.round(heading)%360:null,centre=[point.latitude,point.longitude];
  if(marker)map.removeLayer(marker);if(ray)map.removeLayer(ray);if(arrow)map.removeLayer(arrow);const L=leafletApi;
  marker=L.circleMarker(centre,{radius:7,color:'#fff5d7',weight:3,fillColor:'#ae873c',fillOpacity:1}).addTo(map);
  if(angle!==null){const bounds=map.getBounds(),edge=[bounds.getNorth(),bounds.getEast()],radius=Math.max(50,Math.min(3000000,map.distance(map.getCenter(),edge)*.9)),points=qiblaMapRay(point.latitude,point.longitude,heading,radius);ray=L.layerGroup([L.polyline(points,{color:'#17243b',weight:7,opacity:.95,interactive:false}),L.polyline(points,{color:'#dcc58e',weight:3,opacity:1,interactive:false})]).addTo(map);const end=points[points.length-1];arrow=L.marker(end,{interactive:false,keyboard:false,icon:L.divIcon({className:'qibla-map-direction',html:'<span aria-hidden="true" style="transform:rotate('+heading+'deg)">▲</span>',iconSize:[34,34],iconAnchor:[17,17]})}).addTo(map);}
  uiParts(status,[qiblaPart(label),...(following&&currentPosition?[metres>0?{key:'qiblaUi.mapAccuracy',fallback:QIBLA_UI_SOURCE.mapAccuracy,parameters:{metres:Math.ceil(metres)}}:qiblaPart(' · точность не указана')]:[]),' · ',angle===null?qiblaPart('Направление для этой точки не определено'):{key:'qiblaUi.angleFromNorth',fallback:QIBLA_UI_SOURCE.angleFromNorth,parameters:{angle}},...(hadTileError?[qiblaPart(' · Подложка карты загружается не полностью.')]:[])]);
 }
 // All point selection is transient: no writes to city, history, account or analytics.
 loadLibrary().then(L=>{if(closed||!canvas.isConnected)return;if(!L)throw Error();leafletApi=L;map=L.map(canvas,{zoomControl:false,attributionControl:true,worldCopyJump:true}).setView(point?[point.latitude,point.longitude]:[25,35],currentPosition?(metres>300?14:17):point?13:3);L.control.zoom({position:'topleft',zoomInTitle:uiMessage('qiblaUi.zoomMapIn','Приблизить карту'),zoomOutTitle:uiMessage('qiblaUi.zoomMapOut','Отдалить карту')}).addTo(map);qiblaMapControls(host);
  L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,minZoom:2,keepBuffer:0,updateWhenIdle:true,updateWhenZooming:false,referrerPolicy:'origin',attribution:'&copy; <a href="https://www.openstreetmap.org/copyright" target="_blank" rel="noopener">OpenStreetMap</a> contributors'}).on('tileerror',()=>{hadTileError=true;if(point)update();else uiSet(status,"qiblaUi.mapLoadFailed","Не удалось загрузить карту. Проверьте интернет.");}).addTo(map);
  map.on('click',e=>{const next=mapPoint(e.latlng.lat,e.latlng.lng);if(!next)return;request++;locating?.abort();locating=null;locate.disabled=false;if(accuracy){map.removeLayer(accuracy);accuracy=null;}following=false;point=next;label='Выбранная точка';update();});map.on('zoomend moveend',update);if(currentPosition)setPosition(currentPosition);else update();if(!point)uiSet(status,"qiblaUi.chooseMapPoint","Выберите точку на карте или нажмите «Моё место».");
 }).catch(()=>{if(!closed)uiSet(status,"qiblaUi.mapUnavailable","Карта недоступна. Проверьте интернет и откройте её ещё раз.");});
 function setPosition(position,{force=false}={}){
  if(closed)return false;const focus=force||!currentPosition||!position;currentPosition=position;if(!following&&!force)return false;const next=position?mapPoint(position.coords?.latitude,position.coords?.longitude):cityPoint;
  if(position&&!next){uiSet(status,"qiblaUi.latitudeUnsupported","Местоположение получено, но эта широта недоступна на карте. Используйте компас.");return false;}following=true;point=next;metres=position&&Number.isFinite(position.coords.accuracy)?Math.max(0,position.coords.accuracy):0;
  label=position?(metres>100?'Приблизительное местоположение устройства':'Местоположение устройства'):cityPoint?'Центр выбранного города: '+city.name:'Выбранная точка';
  if(map){if(accuracy){map.removeLayer(accuracy);accuracy=null;}if(point&&metres>0)accuracy=leafletApi.circle([point.latitude,point.longitude],{radius:metres,color:'#287bbe',weight:1,fillOpacity:.1}).addTo(map);if(point&&focus)map.setView([point.latitude,point.longitude],position?(metres>300?14:17):13);update();}return true;
 }
 locate.onclick=async()=>{if(!map||closed||locating)return;const id=++request;locating=new AbortController();following=true;locate.disabled=true;uiSet(status,"qiblaUi.findingYourLocation","Определяем ваше местоположение…");try{
 const position=await getPosition({signal:locating.signal});if(closed||id!==request)return;setPosition(position,{force:true});
 }catch(error){if(!closed&&id===request)uiParts(status,[qiblaPart(error?.code===1?'Доступ к местоположению закрыт.':'Не удалось определить текущее место.'),' ',qiblaPart(label.startsWith('Центр выбранного города:')?'На карте центр выбранного города, а не ваше местоположение.':point?(label.includes('местоположение устройства')?'Показана последняя полученная точка устройства. Можно повторить кнопкой «Моё место».':'На карте выбранная вами точка. Нажмите «Моё место», чтобы повторить.'):'Выберите дом касанием карты.')]);}finally{if(id===request){locating=null;locate.disabled=false;}}};
 back.onclick=()=>{if(!map||!cityPoint)return;request++;locating?.abort();locating=null;locate.disabled=false;if(accuracy){map.removeLayer(accuracy);accuracy=null;}following=false;point=cityPoint;label='Центр выбранного города: '+city.name;map.setView([point.latitude,point.longitude],13);update();};
 return{setPosition,resize(){if(!closed&&map){map.invalidateSize();update();}},destroy(){if(closed)return;closed=true;stopLanguage();request++;locating?.abort();map?.remove();map=null;}};
}
